cd /workspace && python3 -c "
import docx, re
d=docx.Document('output/offer_letter_filled.docx')
def paras(doc):
    for p in doc.paragraphs: yield p
    for t in doc.tables:
        for row in t.rows:
            for c in row.cells:
                for p in c.paragraphs: yield p
txt=[]
for p in paras(d):
    t=''.join(r.text for r in p.runs)
    if t.strip(): txt.append(t)
full='\n'.join(txt)
print('--- leftover markers:', re.findall(r'\{\{[^}]*\}\}', full))
print('--- RELOCATION words present:', [w for w in ['Relocation','relocation','2,125'] if w in full])
print('--- sample ---')
print(full[:1500])
"

cd /workspace && python3 -c "
import docx, re
d=docx.Document('output/offer_letter_filled.docx')
for s in d.sections:
    for name,part in [('hdr',s.header),('ftr',s.footer),('fp_hdr',s.first_page_header),('fp_ftr',s.first_page_footer)]:
        if part is None: continue
        t='\n'.join(''.join(r.text for r in p.runs) for p in part.paragraphs).strip()
        if t: print(name,'::',t)
" && echo "--- input integrity ---" && md5sum inputs/offer_letter_template.docx inputs/employee_data.json
